PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS department(department_id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS user_account(user_id INTEGER PRIMARY KEY AUTOINCREMENT,department_id INTEGER REFERENCES department(department_id) ON DELETE SET NULL,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,email TEXT UNIQUE,role TEXT NOT NULL CHECK(role IN ('ADMINISTRATOR','LECTURER','HOD','STUDENT')),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS course(course_id INTEGER PRIMARY KEY AUTOINCREMENT,department_id INTEGER NOT NULL REFERENCES department(department_id),course_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT,is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS lecturer_course(lecturer_id INTEGER NOT NULL REFERENCES user_account(user_id),course_id INTEGER NOT NULL REFERENCES course(course_id),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(lecturer_id,course_id));
CREATE TABLE IF NOT EXISTS enrolment(enrolment_id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES user_account(user_id),course_id INTEGER NOT NULL REFERENCES course(course_id),enrolled_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,course_id));
CREATE TABLE IF NOT EXISTS assignment(assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL REFERENCES course(course_id),lecturer_id INTEGER NOT NULL,title TEXT NOT NULL,instructions TEXT,deadline TEXT NOT NULL,max_mark REAL NOT NULL CHECK(max_mark>0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(lecturer_id,course_id) REFERENCES lecturer_course(lecturer_id,course_id));
CREATE TABLE IF NOT EXISTS extension_grant(extension_id INTEGER PRIMARY KEY AUTOINCREMENT,assignment_id INTEGER NOT NULL REFERENCES assignment(assignment_id) ON DELETE CASCADE,student_id INTEGER NOT NULL REFERENCES user_account(user_id),granted_by INTEGER NOT NULL REFERENCES user_account(user_id),revised_deadline TEXT NOT NULL,reason TEXT NOT NULL,granted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(assignment_id,student_id));
CREATE TABLE IF NOT EXISTS submission(submission_id INTEGER PRIMARY KEY AUTOINCREMENT,assignment_id INTEGER NOT NULL REFERENCES assignment(assignment_id),student_id INTEGER NOT NULL REFERENCES user_account(user_id),submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,file_name TEXT NOT NULL,file_location TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','LATE','MARKED','MODERATED','RELEASED')),version_no INTEGER NOT NULL DEFAULT 1 CHECK(version_no>=1),UNIQUE(assignment_id,student_id,version_no));
CREATE TABLE IF NOT EXISTS mark_record(mark_id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL UNIQUE REFERENCES submission(submission_id),lecturer_id INTEGER NOT NULL REFERENCES user_account(user_id),mark_value REAL NOT NULL CHECK(mark_value>=0),feedback TEXT NOT NULL,moderation_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(moderation_status IN ('PENDING','RETURNED','APPROVED','RELEASED')),marked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,moderated_by INTEGER REFERENCES user_account(user_id),moderated_at TEXT,released_by INTEGER REFERENCES user_account(user_id),released_at TEXT);
CREATE TABLE IF NOT EXISTS audit_log(audit_id INTEGER PRIMARY KEY AUTOINCREMENT,mark_id INTEGER REFERENCES mark_record(mark_id) ON DELETE SET NULL,actor_id INTEGER NOT NULL REFERENCES user_account(user_id),action_type TEXT NOT NULL,changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,old_value REAL,new_value REAL,reason TEXT,details TEXT);
CREATE INDEX IF NOT EXISTS ix_assignment_course_deadline ON assignment(course_id,deadline);
CREATE INDEX IF NOT EXISTS ix_submission_student_status ON submission(student_id,status);
CREATE INDEX IF NOT EXISTS ix_mark_moderation_status ON mark_record(moderation_status);
